// AI-powered skills summary — Netlify Background Function
// POST /.netlify/functions/teacher-ai-skills-summary-background
// Auth: Requires teacher session cookie
// Body: { job_id, student_code, iep_goals, dese_standards }
//
// Netlify background functions run for up to 15 minutes and always return 202
// to the client immediately. The job_id must be generated by the client and
// included in the request body so it can be used to poll the status endpoint.
//
// Flow:
//   1. Verify teacher auth
//   2. Insert a job row into Supabase ai_jobs with status 'pending'
//   3. Check for a recent cached result (same payload_hash, last 24h)
//   4. If cache hit → update job to 'complete' immediately
//   5. Otherwise → call OpenAI (up to 3 retries with backoff) → update job

console.log('[teacher-ai-skills-summary-background] Module loaded');

const { requireTeacher } = require('./_lib/auth');
const {
  generateRequestId,
  validateBodySize,
  safeJsonParse,
} = require('./_lib/http');
const { getSupabaseConfig } = require('./_lib/supa');
const crypto = require('crypto');

const { SESSION_SECRET } = process.env;

/** UUID v4 regex for validating client-supplied job_id values */
const UUID_V4_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

// ── Prompt helpers (kept in sync with teacher-ai-skills-summary.js) ─────────

function sanitizeForPrompt(value, maxLen = 200) {
  if (value === null || value === undefined) return '';
  return String(value).replace(/[\r\n\t]/g, ' ').slice(0, maxLen);
}

function sanitizeNumber(value) {
  const n = parseFloat(value);
  return isNaN(n) ? 'N/A' : String(n);
}

function buildSkillsPrompt({ student_code, iep_goals, dese_standards }) {
  const safeCode = sanitizeForPrompt(student_code, 20);
  let prompt = `You are an educational data analyst for a special education teacher.\n`;
  prompt += `Analyze the following performance data for student ${safeCode} and write a 2-3 sentence summary for each skill area.\n`;
  prompt += `Use encouraging but honest language. Be specific about the numbers.\n`;
  prompt += `If performance is below 40%, flag it as needing immediate attention.\n\n`;

  if (Array.isArray(iep_goals) && iep_goals.length > 0) {
    prompt += `IEP Goals:\n`;
    for (const g of iep_goals) {
      const code = sanitizeForPrompt(g.code, 50);
      const area = sanitizeForPrompt(g.area, 100);
      const trend = sanitizeForPrompt(g.trend, 10);
      prompt += `- Code: ${code}, Area: ${area}, Current average: ${sanitizeNumber(g.current_avg)}%, Trend: ${trend}, Data points: ${sanitizeNumber(g.data_points)}, Target: ${sanitizeNumber(g.target)}%, Baseline: ${sanitizeNumber(g.baseline)}%\n`;

      if (Array.isArray(g.question_weaknesses) && g.question_weaknesses.length > 0) {
        prompt += `  Specific skill struggles for ${code}:\n`;
        const limitedWeaknesses = g.question_weaknesses
          .slice()
          .sort((a, b) => (a.accuracy ?? 100) - (b.accuracy ?? 100))
          .slice(0, 5);
        for (const q of limitedWeaknesses) {
          const qText = sanitizeForPrompt(q.text, 100);
          const qAcc = sanitizeNumber(q.accuracy);
          const qAttempts = sanitizeNumber(q.attempts);
          prompt += `    * "${qText}" — ${qAcc}% accuracy over ${qAttempts} attempt${q.attempts === 1 ? '' : 's'}\n`;
        }
      }
    }
    prompt += `\n`;
  }

  if (Array.isArray(dese_standards) && dese_standards.length > 0) {
    prompt += `DESE Standards (from graded assignments):\n`;
    for (const d of dese_standards) {
      const code = sanitizeForPrompt(d.code, 50);
      prompt += `- Code: ${code}, Score: ${sanitizeNumber(d.percent_correct)}%, Items graded: ${sanitizeNumber(d.item_count)}\n`;
    }
    prompt += `\n`;
  }

  prompt += `Return a JSON object with a single "skills" array. Each element must have:\n`;
  prompt += `  "code": the goal or DESE code exactly as provided\n`;
  prompt += `  "description": a thorough, IEP-ready description of this skill area. For DESE/MLS standards, include the full strand name, cluster, and specific skill being measured (e.g. "Reading — Key Ideas & Details: Draw inferences from the text; cite specific textual evidence to support conclusions drawn from the text, including determining where the text leaves matters uncertain"). For IEP goals, include the goal area, a clear restatement of what the goal measures, and the specific skill deficit being addressed. Write this so a SPED teacher could paste it directly into an IEP goal bank or present-levels narrative.\n`;
  prompt += `  "summary": a 2-3 sentence narrative about performance in this skill area\n`;
  prompt += `  "tier": one of "excellent" (>=80%), "on-track" (60-79%), "needs-support" (40-59%), "critical" (<40%)\n`;
  prompt += `  "source": "iep" if the code came from the IEP Goals section, or "dese" if it came from the DESE Standards section\n`;
  prompt += `  "goal_recommendation": only include this field when tier is "needs-support" or "critical". Write a 1-2 sentence draft IEP goal recommendation a SPED teacher could use as a starting point. Reference the specific skill deficit, suggest a measurable target, and use language consistent with Missouri IEP goal-writing conventions (e.g. "Given grade-level text, [student] will identify the main idea and two supporting details with 70% accuracy across 3 consecutive data points by the next annual review."). Omit this field entirely for "excellent" and "on-track" tiers.\n`;
  prompt += `Include every IEP goal and every DESE standard provided. Do not add or remove entries.\n`;
  prompt += `Example: { "skills": [{ "code": "MLS.R.1.A",`;
  prompt += ` "description": "Reading — Key Ideas & Details: Draw inferences from the text; cite specific textual evidence when analyzing what the text says explicitly and what can be inferred",`;
  prompt += ` "summary": "...", "tier": "needs-support", "source": "dese",`;
  prompt += ` "goal_recommendation": "Given grade-level narrative text, the student will identify explicit details and make text-based inferences with 65% accuracy across 3 consecutive probes by the next annual IEP review." }] }`;

  return prompt;
}

// ── Payload hash (for caching) ───────────────────────────────────────────────

function computePayloadHash(student_code, iep_goals, dese_standards) {
  const canonical = JSON.stringify({ student_code, iep_goals, dese_standards });
  return crypto.createHash('sha256').update(canonical).digest('hex');
}

// ── Supabase helpers ─────────────────────────────────────────────────────────

function supabaseHeaders(key) {
  return {
    apikey: key,
    Authorization: `Bearer ${key}`,
    'Content-Type': 'application/json',
    Prefer: 'return=representation',
  };
}

async function insertJob(url, key, { id, student_code, payload_hash, created_by }) {
  const res = await fetch(`${url}/rest/v1/ai_jobs`, {
    method: 'POST',
    headers: supabaseHeaders(key),
    body: JSON.stringify({
      id,
      student_code,
      payload_hash,
      status: 'pending',
      created_by,
    }),
  });
  return res.ok;
}

async function findCachedJob(url, key, payload_hash) {
  const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  const res = await fetch(
    `${url}/rest/v1/ai_jobs?payload_hash=eq.${encodeURIComponent(payload_hash)}&status=eq.complete&created_at=gte.${encodeURIComponent(since)}&order=created_at.desc&limit=1&select=result`,
    {
      method: 'GET',
      headers: supabaseHeaders(key),
    }
  );
  if (!res.ok) return null;
  const rows = await res.json();
  return Array.isArray(rows) && rows.length > 0 ? rows[0].result : null;
}

async function updateJob(url, key, id, patch) {
  const res = await fetch(
    `${url}/rest/v1/ai_jobs?id=eq.${encodeURIComponent(id)}`,
    {
      method: 'PATCH',
      headers: supabaseHeaders(key),
      body: JSON.stringify({ ...patch, updated_at: new Date().toISOString() }),
    }
  );
  return res.ok;
}

// ── OpenAI call with retries ─────────────────────────────────────────────────

/** Per-attempt timeout for OpenAI API calls.
 * Background functions have a 15-minute ceiling, so we allow 90 seconds per attempt
 * and up to 3 attempts (worst case: ~96s total including 2s + 4s backoff delays).
 */
const OPENAI_TIMEOUT_MS = 90000;

const VALID_TIERS = new Set(['excellent', 'on-track', 'needs-support', 'critical']);

function sanitizeSkills(skills) {
  if (!Array.isArray(skills)) return null;
  return skills
    .filter(s => s && typeof s.code === 'string' && s.code.trim() !== '')
    .map(s => ({
      code: s.code.trim(),
      description: typeof s.description === 'string' ? s.description.trim() : '',
      summary: typeof s.summary === 'string' ? s.summary.trim() : '',
      tier: VALID_TIERS.has(s.tier) ? s.tier : 'needs-support',
      source: s.source === 'dese' ? 'dese' : 'iep',
      ...(typeof s.goal_recommendation === 'string' && s.goal_recommendation.trim() !== ''
        ? { goal_recommendation: s.goal_recommendation.trim() }
        : {}),
    }));
}

async function callOpenAiWithRetries(prompt, apiKey, requestId, maxAttempts = 3) {
  let lastError = 'Unknown error';
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      console.log(`[teacher-ai-skills-summary-background] [${requestId}] OpenAI attempt ${attempt}/${maxAttempts}`);
      const res = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          temperature: 0.3,
          max_tokens: 4000,
          response_format: { type: 'json_object' },
          messages: [{ role: 'system', content: prompt }],
        }),
        signal: AbortSignal.timeout(OPENAI_TIMEOUT_MS),
      });

      if (!res.ok) {
        const errText = await res.text().catch(() => '');
        lastError = `OpenAI API error: ${res.status} ${errText}`;
        console.error(`[teacher-ai-skills-summary-background] [${requestId}] ${lastError}`);
        // Don't retry on 4xx (bad request / auth) — only retry on 5xx / network errors
        if (res.status >= 400 && res.status < 500) break;
      } else {
        const data = await res.json();
        const content = data?.choices?.[0]?.message?.content;
        if (!content) {
          lastError = 'OpenAI returned empty content';
          console.error(`[teacher-ai-skills-summary-background] [${requestId}] ${lastError}`);
        } else {
          const parsed = JSON.parse(content);
          const sanitized = sanitizeSkills(parsed?.skills);
          if (!sanitized) {
            lastError = 'OpenAI response missing skills array';
            console.error(`[teacher-ai-skills-summary-background] [${requestId}] ${lastError}`);
          } else {
            return { ok: true, skills: sanitized };
          }
        }
      }
    } catch (err) {
      lastError = err.message || 'Fetch failed';
      console.error(`[teacher-ai-skills-summary-background] [${requestId}] Attempt ${attempt} failed: ${lastError}`);
    }

    if (attempt < maxAttempts) {
      const backoffMs = Math.min(Math.pow(2, attempt) * 1000, 30000);
      console.log(`[teacher-ai-skills-summary-background] [${requestId}] Retrying in ${backoffMs}ms…`);
      await new Promise(r => setTimeout(r, backoffMs));
    }
  }
  return { ok: false, error: lastError };
}

// ── Handler ──────────────────────────────────────────────────────────────────

exports.handler = async (event) => {
  const requestId = generateRequestId();
  console.log(`[teacher-ai-skills-summary-background] [${requestId}] Request received - method: ${event.httpMethod}`);

  if (event.httpMethod !== 'POST') {
    return { statusCode: 405, body: 'Method Not Allowed' };
  }

  // Verify teacher session
  const auth = requireTeacher(event, SESSION_SECRET);
  if (!auth.ok) {
    console.log(`[teacher-ai-skills-summary-background] [${requestId}] Unauthorized`);
    return { statusCode: 401, body: 'Unauthorized' };
  }

  const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
  if (!OPENAI_API_KEY) {
    console.warn(`[teacher-ai-skills-summary-background] [${requestId}] OPENAI_API_KEY not configured`);
    return { statusCode: 503, body: 'AI not configured' };
  }

  const { url: SUPABASE_URL, key: SUPABASE_KEY } = getSupabaseConfig();
  if (!SUPABASE_URL || !SUPABASE_KEY) {
    console.warn(`[teacher-ai-skills-summary-background] [${requestId}] Supabase not configured`);
    return { statusCode: 503, body: 'Persistence layer not configured' };
  }

  // Validate body size
  const bodySizeCheck = validateBodySize(event.body, 30);
  if (!bodySizeCheck.valid) {
    return { statusCode: 400, body: 'Request body too large' };
  }

  // Parse body
  const parseResult = safeJsonParse(event.body);
  if (!parseResult.ok) {
    return { statusCode: 400, body: 'Invalid JSON' };
  }

  const { job_id, student_code, iep_goals, dese_standards } = parseResult.data;

  // Validate job_id (must be a UUID v4 from the client)
  if (!job_id || typeof job_id !== 'string' || !UUID_V4_RE.test(job_id)) {
    return { statusCode: 400, body: 'job_id must be a valid UUID v4' };
  }

  if (!student_code || typeof student_code !== 'string' || student_code.trim() === '') {
    return { statusCode: 400, body: 'student_code is required' };
  }

  const hasGoals = Array.isArray(iep_goals) && iep_goals.length > 0;
  const hasStandards = Array.isArray(dese_standards) && dese_standards.length > 0;
  if (!hasGoals && !hasStandards) {
    return { statusCode: 400, body: 'At least one of iep_goals or dese_standards must be provided' };
  }

  const createdBy = auth.user.username;
  const payloadHash = computePayloadHash(student_code, iep_goals || [], dese_standards || []);

  // Insert the pending job record
  const inserted = await insertJob(SUPABASE_URL, SUPABASE_KEY, {
    id: job_id,
    student_code,
    payload_hash: payloadHash,
    created_by: createdBy,
  });

  if (!inserted) {
    console.error(`[teacher-ai-skills-summary-background] [${requestId}] Failed to insert job ${job_id}`);
    return { statusCode: 500, body: 'Failed to create job' };
  }

  console.log(`[teacher-ai-skills-summary-background] [${requestId}] Job ${job_id} created for student ${student_code}`);

  // Background work begins here — client already received 202 from Netlify

  // Check cache first
  try {
    const cached = await findCachedJob(SUPABASE_URL, SUPABASE_KEY, payloadHash);
    if (cached) {
      console.log(`[teacher-ai-skills-summary-background] [${requestId}] Cache hit for ${student_code} — using cached result`);
      await updateJob(SUPABASE_URL, SUPABASE_KEY, job_id, {
        status: 'complete',
        result: cached,
      });
      return { statusCode: 202, body: '' };
    }
  } catch (cacheErr) {
    console.warn(`[teacher-ai-skills-summary-background] [${requestId}] Cache check failed: ${cacheErr.message} — proceeding to OpenAI`);
  }

  // Call OpenAI
  const systemPrompt = buildSkillsPrompt({
    student_code,
    iep_goals: iep_goals || [],
    dese_standards: dese_standards || [],
  });

  const aiResult = await callOpenAiWithRetries(systemPrompt, OPENAI_API_KEY, requestId);

  if (aiResult.ok) {
    console.log(`[teacher-ai-skills-summary-background] [${requestId}] Job ${job_id} complete — ${aiResult.skills.length} skills`);
    await updateJob(SUPABASE_URL, SUPABASE_KEY, job_id, {
      status: 'complete',
      result: { skills: aiResult.skills },
    });
  } else {
    console.error(`[teacher-ai-skills-summary-background] [${requestId}] Job ${job_id} failed: ${aiResult.error}`);
    await updateJob(SUPABASE_URL, SUPABASE_KEY, job_id, {
      status: 'error',
      error: aiResult.error,
    });
  }

  return { statusCode: 202, body: '' };
};
